package com.example.consumer;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.SQSEvent;
import com.amazonaws.services.lambda.runtime.events.SQSEvent.SQSMessage;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Map;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

public class OrderEventConsumer implements RequestHandler<SQSEvent, Void> {

    private static final String GRAPHQL_ENDPOINT = System.getenv("GRAPHQL_ENDPOINT");
    private static final String SERVICE_API_KEY = System.getenv("SERVICE_API_KEY");
    private static final HttpClient httpClient = HttpClient.newHttpClient();
    private static final Gson gson = new Gson();

    @Override
    public Void handleRequest(SQSEvent event, Context context) {
        for (SQSMessage message : event.getRecords()) {
            try {
                processOrderMessage(message, context);
            } catch (Exception e) {
                context.getLogger().log("Error processing message: " + e.getMessage());
                throw new RuntimeException("Failed to process SQS message", e);
            }
        }
        return null;
    }

    private void processOrderMessage(SQSMessage message, Context context) throws Exception {
        JsonObject body = JsonParser.parseString(message.getBody()).getAsJsonObject();

        String orderId = body.get("orderId").getAsString();
        String customerName = body.get("customerName").getAsString();
        String status = body.get("status").getAsString();
        String notes = body.has("notes") ? body.get("notes").getAsString() : "";

        // Validate orderId format
        if (!orderId.matches("^ORD-[0-9]{6,12}$")) {
            context.getLogger().log("Invalid orderId format: " + orderId);
            return;
        }

        // Build GraphQL mutation to update order tracking system
        String mutation = buildUpdateMutation(orderId, customerName, status, notes);

        context.getLogger().log("Executing mutation for order: " + orderId);

        String responseBody = executeGraphQL(mutation);

        JsonObject response = JsonParser.parseString(responseBody).getAsJsonObject();
        if (response.has("errors")) {
            context.getLogger().log("GraphQL errors: " + response.get("errors").toString());
        }
    }

    private String buildUpdateMutation(String orderId, String customerName, String status, String notes) {
        // Construct GraphQL mutation with string interpolation
        // Note: orderId is validated above, but other fields come directly from SQS message
        StringBuilder sb = new StringBuilder();
        sb.append("mutation { updateOrderTracking(");
        sb.append("orderId: \"" + orderId + "\", ");
        sb.append("customerName: \"" + customerName + "\", ");
        sb.append("status: \"" + status + "\", ");
        sb.append("notes: \"" + notes + "\"");
        sb.append(") { id customerName status updatedAt } }");
        return sb.toString();
    }

    private String executeGraphQL(String query) throws Exception {
        JsonObject payload = new JsonObject();
        payload.addProperty("query", query);

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(GRAPHQL_ENDPOINT))
                .header("Content-Type", "application/json")
                .header("x-api-key", SERVICE_API_KEY)
                .POST(HttpRequest.BodyPublishers.ofString(gson.toJson(payload)))
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() != 200) {
            throw new RuntimeException("GraphQL request failed with status: " + response.statusCode());
        }

        return response.body();
    }

    // Lambda Function URL handler for manual replay of failed messages
    public Map<String, Object> handleFunctionUrl(Map<String, Object> event, Context context) {
        @SuppressWarnings("unchecked")
        Map<String, String> headers = (Map<String, String>) event.get("headers");
        String body = (String) event.get("body");

        if (body == null || body.isEmpty()) {
            return Map.of("statusCode", 400, "body", "{\"error\": \"Missing body\"}");
        }

        // Parse the replay request
        JsonObject replayRequest = JsonParser.parseString(body).getAsJsonObject();
        String messageBody = replayRequest.get("messageBody").getAsString();

        // Create a synthetic SQS message for reprocessing
        SQSMessage syntheticMessage = new SQSMessage();
        syntheticMessage.setBody(messageBody);

        try {
            processOrderMessage(syntheticMessage, context);
            return Map.of("statusCode", 200, "body", "{\"status\": \"replayed\"}");
        } catch (Exception e) {
            return Map.of("statusCode", 500, "body", "{\"error\": \"" + e.getMessage() + "\"}");
        }
    }
}
